use super::*;
use super::super::{native_multi_map_resources::{self,Inputs},native_multi_map_runtime::{Runtime,Action,UiPage},native_resources::BytePin};
use std::{path::Path,fs,thread,time::{Duration,Instant},sync::atomic::Ordering};use sha2::{Digest,Sha256};use serde_json::{Value,json};
fn inputs(name:&str)->Inputs{let p=Path::new(env!("CARGO_MANIFEST_DIR"));let manifest=p.join(format!("logs/continuation-20261003/{name}"));let b=fs::read(&manifest).unwrap();Inputs{project:p.into(),manifest,manifest_pin:BytePin{bytes:b.len() as u64,sha256:Sha256::digest(b).into()}}}
fn wait(mut f:impl FnMut()->bool){let until=Instant::now()+Duration::from_secs(90);while !f(){assert!(Instant::now()<until,"R477 finite wait timeout");thread::sleep(Duration::from_millis(5));}}
fn reference(p:&Path)->Vec<u8>{let mut d=png::Decoder::new(fs::File::open(p).unwrap()).read_info().unwrap();let mut b=vec![0;d.output_buffer_size()];let i=d.next_frame(&mut b).unwrap();assert_eq!(i.color_type,png::ColorType::Rgba);b.truncate(i.buffer_size());b}
fn save(path:&Path,frame:&super::super::native_multi_map_runtime::UiFrame)->Value{let rgba:Vec<_>=frame.bgra().unwrap().chunks_exact(4).flat_map(|p|[p[2],p[1],p[0],p[3]]).collect();let mut e=png::Encoder::new(fs::File::create(path).unwrap(),800,600);e.set_color(png::ColorType::Rgba);e.set_depth(png::BitDepth::Eight);e.write_header().unwrap().write_image_data(&rgba).unwrap();let raw=fs::read(path).unwrap();json!({"path":path,"bytes":raw.len(),"sha256":format!("{:X}",Sha256::digest(raw)),"rgba_sha256":format!("{:X}",Sha256::digest(&rgba)),"identity":[frame.identity().0,frame.identity().1]})}
fn fixture(root:&Path,m:&Value,name:&str)->Inputs{let path=root.join(name);let b=serde_json::to_vec_pretty(m).unwrap();fs::write(&path,&b).unwrap();Inputs{project:Path::new(env!("CARGO_MANIFEST_DIR")).into(),manifest:path,manifest_pin:BytePin{bytes:b.len() as u64,sha256:Sha256::digest(&b).into()}}}
#[test]fn actual_two_native_maps_scroll_press_clipped_rows_switch_cancel_and_identity(){
 let p=Path::new(env!("CARGO_MANIFEST_DIR"));let root=p.join("target/r477-multi-map");let i=inputs("r477-multi-map-binding.json");let skin=inputs("r476-native-menu-skin-binding.json");let m:Value=serde_json::from_slice(&fs::read(&i.manifest).unwrap()).unwrap();let(_,bindings,rows)=native_multi_map_resources::load(&i).unwrap();assert_eq!(rows.len(),40);assert_eq!(bindings.len(),2);assert_eq!(rows.iter().filter(|r|r.available).map(|r|(r.choice.mode,r.choice.map_id)).collect::<Vec<_>>(),[(1,564),(1,514)]);let mut negative=0;
 let mut menu=Menu::new(40,4).unwrap();assert!(!menu.enabled(Hit::Up));assert!(menu.enabled(Hit::Down));menu.down(Some(Hit::Down));assert_eq!(menu.pressed,Some(Hit::Down));assert_eq!(menu.top,0);menu.pointer_move(None);assert!(menu.pressed.is_none());menu.pointer_move(Some(Hit::Down));assert_eq!(menu.pressed,Some(Hit::Down));assert!(menu.release(Some(Hit::Down)));assert_eq!(menu.top,1);menu.down(Some(Hit::Up));assert!(!menu.release(None));negative+=1;assert_eq!(menu.top,1);menu.down(Some(Hit::Down));menu.cancel_press();assert!(!menu.release(Some(Hit::Down)));negative+=1;
 for _ in 1..40{menu.down(Some(Hit::Down));menu.release(Some(Hit::Down));}assert_eq!(menu.top,39);assert!(!menu.enabled(Hit::Down));assert_eq!(menu.down(Some(Hit::Row(39))),Some(39));assert_eq!(menu.key(0x24),Some(0));assert_eq!(menu.top,0);assert_eq!(menu.key(0x23),Some(39));assert_eq!(menu.top,34);assert_eq!(menu.key(0x21),Some(33));assert_eq!(menu.top,33);assert_eq!(menu.key(0x22),Some(39));assert_eq!(menu.top,34);
 for (count,selected) in [(0,0),(41,0),(40,40)]{assert!(Menu::new(count,selected).is_none());negative+=1;}
 let mut coordinate_checks=0;
 for(w,h)in[(157,81),(628,324),(1256,648),(800,600),(33,17)]{let l=Layout::fit(24,156,w,h).unwrap();let menu=Menu::new(40,4).unwrap();for row in 0..6{let(a,b,c,d)=Menu::row_rect(&l,row).unwrap();assert!(d-b>=0);if d>b{assert!(Menu::font_height(&l).unsigned_abs() as i32<=d-b||h<81);}for y in b..d{for x in a..c{let(sx,sy)=l.source(x,y).unwrap();let expected=if(142..153).contains(&sx)&&(3..15).contains(&sy){Some(Hit::Up)}else if(141..152).contains(&sx)&&(65..77).contains(&sy){Some(Hit::Down)}else if(9..141).contains(&sx)&&(2..74).contains(&sy){Some(Hit::Row(((sy-2)/12) as usize))}else{None};assert_eq!(menu.hit(&l,x,y),expected);assert_eq!(expected,Some(Hit::Row(row)));coordinate_checks+=1;}}}assert!(menu.hit(&l,l.x-1,l.y).is_none());}
 let mut wrong=m.clone();wrong["bindings"][1]["mode"]=json!(2);assert!(native_multi_map_resources::load(&fixture(&root,&wrong,"wrong-mode.json")).is_err());negative+=1;
 let mut wrong=m.clone();wrong["bindings"][1]["sectors"][0]["map_id"]=json!(564);assert!(native_multi_map_resources::load(&fixture(&root,&wrong,"wrong-sector-map.json")).is_err());negative+=1;
 let mut wrong=m.clone();wrong["bindings"][1]["namespace"]=json!("SHARED_MAP");assert!(native_multi_map_resources::load(&fixture(&root,&wrong,"wrong-namespace.json")).is_err());negative+=1;
 let mut wrong=m.clone();wrong["catalog40"][5]["name"]=json!("Fake Temple");assert!(native_multi_map_resources::load(&fixture(&root,&wrong,"wrong-label.json")).is_err());negative+=1;
 let mut rt=Runtime::start_with_menu_skin(i,skin.clone()).unwrap();assert!(rt.handle(Action::Select(1,514)).is_err());negative+=1;wait(||{rt.poll();rt.page()==UiPage::Menu});assert_eq!((rt.choice().unwrap().mode,rt.choice().unwrap().map_id),(1,564));
 rt.handle(Action::Select(0,565)).unwrap();assert!(rt.handle(Action::Enter).is_err());negative+=1;assert_eq!(rt.choice().unwrap().map_id,565);assert!(rt.frame().is_none());assert!(rt.handle(Action::Select(2,514)).is_err());negative+=1;assert_eq!(rt.choice().unwrap().map_id,565);
 rt.handle(Action::Select(1,564)).unwrap();rt.handle(Action::Enter).unwrap();wait(||rt.progress().frames_produced.load(Ordering::Acquire)==1);rt.handle(Action::Select(1,514)).unwrap();rt.poll();assert_eq!(rt.stale_results_rejected,1);assert!(rt.frame().is_none());negative+=1;
 rt.handle(Action::Enter).unwrap();wait(||{rt.poll();rt.page()==UiPage::Preview});let temple=rt.frame().unwrap();assert_eq!(temple.identity(),(1,514));let temple_image=save(&root.join("cpu-temple514.png"),&temple);assert_eq!(reference(Path::new(temple_image["path"].as_str().unwrap())),reference(Path::new(m["probe_reference"]["path"].as_str().unwrap())));
 rt.handle(Action::Back).unwrap();assert_eq!(rt.choice().unwrap().map_id,514);rt.handle(Action::Enter).unwrap();wait(||{rt.poll();rt.page()==UiPage::Preview});let held=rt.frame().unwrap();let before=rt.progress().frames_produced.load(Ordering::Acquire);rt.handle(Action::Pan(48,0)).unwrap();wait(||rt.progress().frames_produced.load(Ordering::Acquire)>before);rt.handle(Action::Select(1,564)).unwrap();assert!(held.bgra().is_err());negative+=1;rt.poll();assert!(rt.stale_results_rejected>=2&&rt.frame().is_none());negative+=1;
 rt.handle(Action::Enter).unwrap();wait(||{rt.poll();rt.page()==UiPage::Preview});let battle=rt.frame().unwrap();assert_eq!(battle.identity(),(1,564));let battle_image=save(&root.join("cpu-battle564.png"),&battle);assert_ne!(temple_image["rgba_sha256"],battle_image["rgba_sha256"]);assert_eq!(reference(Path::new(battle_image["path"].as_str().unwrap())),reference(&p.join("target/r474-offline-map-flow/01-entry-battle-ground.png")));
 rt.handle(Action::Back).unwrap();assert_eq!(rt.choice().unwrap().map_id,564);rt.handle(Action::Select(1,514)).unwrap();rt.handle(Action::Enter).unwrap();wait(||rt.progress().load_active.load(Ordering::Acquire));rt.handle(Action::Select(1,564)).unwrap();assert_eq!(rt.page(),UiPage::Menu);assert!(rt.frame().is_none());rt.handle(Action::Close).unwrap();wait(||{rt.poll();rt.page()==UiPage::Closed});assert!(rt.progress().retired.load(Ordering::Acquire));
 let mut missing=m.clone();let missing_root=root.join("actual-missing-native-map");missing["bindings"][1]["map_root"]=json!(missing_root);missing["bindings"][1]["sectors"][0]["pin"]["path"]=json!(missing_root.join("514/80008000.s32"));let mut fail=Runtime::start_with_menu_skin(fixture(&root,&missing,"missing-sector.json"),skin).unwrap();wait(||{fail.poll();fail.page()==UiPage::Menu});fail.handle(Action::Select(1,514)).unwrap();fail.handle(Action::Enter).unwrap();wait(||{fail.poll();fail.page()==UiPage::Menu});assert_eq!(fail.choice().unwrap().map_id,514);assert!(fail.frame().is_none()&&fail.status().contains("載入失敗"));negative+=1;fail.handle(Action::Close).unwrap();wait(||{fail.poll();fail.page()==UiPage::Closed});
 let details=json!({"state":"REAL_TWO_NATIVE_MAPS_EXACT_IDENTITIES_AND_MULTIROW_MENU_STATE_PASS_GUI_PENDING","new_focused_tests":1,"historical_PASS_reruns":0,"catalog_rows":40,"qualified_maps":[[1,564],[1,514]],"unqualified_rows":38,"negative_cases":negative,"coordinate_checks":coordinate_checks,"row_pitch":12,"visible_rows":6,"native_top_maximum":"count-1 (not count-6)","native_arrow_press_release_no_repeat_timer":true,"Modern_keys_and_scaled_clipped_font":true,"Back_preserves_selection":true,"actual_old_map_queued_frame_and_old_pan_discarded":rt.stale_results_rejected,"actual_select_during_native_load_cancelled":true,"held_old_map_frame_revoked":true,"actual_missing514_no_564_fallback":true,"images":[temple_image,battle_image],"Temple_equals_fixed_R476_library_probe_pixels":true,"Battle_equals_fixed_R474_pixels":true,"GUI":0,"LOADED":false});fs::write(p.join("logs/continuation-20261003/r477-multi-map-details.json"),serde_json::to_vec_pretty(&details).unwrap()).unwrap();
}
